+#!/usr/bin/env node
+
+import { readFileSync, realpathSync } from 'node:fs';
+import { fileURLToPath, URL } from 'node:url';
+
+import { add, multiply } from '../src/index.js';
+
+const COMMANDS = {
+  add,
+  multiply,
+};
+
+function usage() {
+  return [
+    'Usage: example-package-name <command> <left> <right>',
+    '',
+    'Commands:',
+    '  add       Add two numbers',
+    '  multiply  Multiply two numbers',
+    '',
+    'Options:',
+    '  --help     Show this help',
+    '  --version  Show package version',
+  ].join('\n');
+}
+
+function readVersion() {
+  const packageUrl = new URL('../package.json', import.meta.url);
+  const packageJson = JSON.parse(readFileSync(packageUrl, 'utf8'));
+  return packageJson.version;
+}
+
+function parseNumber(value, label) {
+  const parsed = Number(value);
+
+  if (!Number.isFinite(parsed)) {
+    throw new Error(`${label} must be a finite number`);
+  }
+
+  return parsed;
+}
+
+export function runCli(
+  argv,
+  { stderr = console.error, stdout = console.log } = {}
+) {
+  const [command, left, right] = argv;
+
+  if (!command || command === '--help' || command === '-h') {
+    stdout(usage());
+    return 0;
+  }
+
+  if (command === '--version' || command === '-v') {
+    stdout(readVersion());
+    return 0;
+  }
+
+  const operation = COMMANDS[command];
+
+  if (!operation) {
+    stderr(`Unknown command: ${command}`);
+    stderr(usage());
+    return 1;
+  }
+
+  try {
+    const leftNumber = parseNumber(left, 'left');
+    const rightNumber = parseNumber(right, 'right');
+    stdout(String(operation(leftNumber, rightNumber)));
+    return 0;
+  } catch (error) {
+    stderr(error.message);
+    return 1;
+  }
+}
+
+function isCliEntryPoint() {
+  if (!process.argv[1]) {
+    return false;
+  }
+
+  try {
+    return (
+      realpathSync(process.argv[1]) ===
+      realpathSync(fileURLToPath(import.meta.url))
+    );
+  } catch {
+    return false;
+  }
+}
+
+if (isCliEntryPoint()) {
+  process.exitCode = runCli(process.argv.slice(2));
+}

