+const log = resolve(process.argv[3] || 'ci-logs/issue-212-baseline.log');
+mkdirSync(dirname(log), { recursive: true });
+const snapshot = mkdtempSync(join(tmpdir(), 'issue-212-baseline-'));
+const tests = [
