+ * `devEngines.packageManager.name` is the bare name.
+ * @param {string} value
+ * @returns {string}
+ */
+function parsePackageManagerName(value) {
+  if (value.startsWith('@')) {
+    const lastAt = value.lastIndexOf('@');
