+          `Too many errors reading the Pages deployment status: ${describe(error)}`,
+          { cause: error }
+        );
+      }
+      log(
+        `Transient failure to read the deployment status (${describe(error)}); ${errors}/${maxPollErrors}.`
+      );
+    }
