+    branch: 'main',
+    remote: 'origin',
+    runId: readEnv('GITHUB_RUN_ID'),
+    mergeAttempts: DEFAULT_MERGE_ATTEMPTS,
+    mergeDelayMs: DEFAULT_MERGE_DELAY_MS,
