+    label,
+    branch,
+    remote,
+    runId,
+    title,
+    body,
+    mergeAttempts,
+    mergeDelayMs,
+    checkAttempts,
+    checkDelayMs,
+    releasePullRequestToken,
+    githubToken,
+    repository,
+    parentSha,
+    runUrl,
