+    'bright',
+    'calm',
+    'cool',
+    'cyan',
+    'dark',
+    'fast',
+    'gold',
+    'good',
+    'green',
+    'happy',
+    'kind',
+    'loud',
+    'neat',
+    'nice',
+    'pink',
+    'proud',
+    'quick',
+    'red',
+    'rich',
+    'safe',
+    'shy',
+    'soft',
+    'sweet',
+    'tall',
+    'warm',
+    'wise',
+    'young',
+  ];
+  const nouns = [
+    'apple',
+    'bird',
+    'book',
+    'car',
+    'cat',
+    'cloud',
+    'desk',
+    'dog',
+    'door',
+    'fish',
+    'flower',
+    'frog',
+    'grass',
+    'house',
+    'key',
+    'lake',
+    'leaf',
+    'moon',
+    'mouse',
+    'owl',
+    'park',
+    'rain',
+    'river',
+    'rock',
+    'sea',
+    'star',
+    'sun',
+    'tree',
+    'wave',
+    'wind',
+  ];
+
+  const randomAdjective =
+    adjectives[Math.floor(Math.random() * adjectives.length)];
+  const randomNoun = nouns[Math.floor(Math.random() * nouns.length)];
