+  if (!versionTypeMatch) {
+    throw new Error(
+      `Could not parse version type from ${filePath}. Expected a changeset header like ${formatChangesetHeader(
+        packageName,
+        'patch'
+      )} with version type major, minor, or patch.`
+    );
+  }
