+  // Revalidate release metadata before every attempt and after any rebase.
+  const push = async () => {
+    for (let attempt = 1; attempt <= 3; attempt++) {
+      if (releaseParent) {
+        await assertReleaseMetadataOnly({
+          runner,
+          parentSha: releaseParent,
+          logger,
+        });
+      }
