+  const root = mkdtempSync(join(tmpdir(), 'sarif-gate-'));
+  try {
+    for (const [index, data] of reports.entries()) {
+      writeFileSync(
+        join(root, `${index}.sarif`),
+        typeof data === 'string' ? data : JSON.stringify(data)
+      );
+    }
+    return spawnSync(
+      'node',
+      [resolve('scripts/check-codeql-results.mjs'), root],
