+    ];
+    const unscoped = [];
+
+    for (const [sourceIndex, source] of sources.entries()) {
+      for (const match of source.matchAll(/cache-(?:from|to): *[^\n]*/g)) {
+        if (/type=gha/.test(match[0]) && !/scope=/.test(match[0])) {
