+  if (sandboxed || process.platform !== 'win32') {
+    return null;
+  }
+  const fixture = mkdtempSync(join(tmpdir(), 'symlink-permission-'));
+  try {
+    symlinkSync(resolve('bin/example-package-name.js'), join(fixture, 'bin'));
