+  } catch (error) {
+    if (error.code === 'EPERM') {
+      return 'Windows file symlinks require developer mode or administrator privileges';
+    }
+    throw error;
+  } finally {
+    rmSync(fixture, { recursive: true, force: true });
+  }
+}
