+  it('resolves $ from the Node < 22.12 CommonJS namespace', () => {
+    const resolved = resolveNamedExport(
+      nodeTwentyNamespace(),
+      '$',
+      'command-stream'
+    );
+    expect(typeof resolved.$).toBe('function');
+  });
+
+  it('resolves $ when use-m already unwrapped the module', () => {
+    const resolved = resolveNamedExport(
+      commandStreamExports(),
+      '$',
+      'command-stream'
+    );
+    expect(typeof resolved.$).toBe('function');
+  });
