+// One error annotation per failure, encoded as a workflow command message.
+export function fail(error) {
+  const text = String(error?.message || error)
+    .replace(/%/g, '%25')
+    .replace(/\r/g, '%0D')
+    .replace(/\n/g, '%0A');
