+  let calls = 0;
+  const client = {
+    getArtifact: async () => { throw notFound(); },
+    deleteArtifact: async () => { throw notFound(); },
+    uploadArtifact: async () => { calls++; throw network(); },
+  };
+  await assert.rejects(uploadWithRetry(client, 'site', ['file'], '/root', {}, noWait), /ENOTFOUND/);
