+#[test]
+fn path_helpers_match_repository_layout() {
+    assert_eq!(get_cargo_toml_path("."), PathBuf::from("./Cargo.toml"));
+    assert_eq!(get_cargo_lock_path("."), PathBuf::from("./Cargo.lock"));
