+  let system = SystemPrompt.header(input.providerID);
+  system.push(
+    ...(() => {
+      const base = input.agent.prompt
+        ? [input.agent.prompt]
+        : SystemPrompt.provider(input.modelID);
+      if (input.appendSystem) {
+        return [base[0] + '\n' + input.appendSystem];
+      }
+      return base;
+    })()
