+export async function createUserMessage(input: PromptInput) {
+  const agent = await Agent.get(input.agent ?? 'build');
+  const info: MessageV2.Info = {
+    id: input.messageID ?? Identifier.ascending('message'),
+    role: 'user',
+    sessionID: input.sessionID,
+    time: {
+      created: Date.now(),
+    },
+    tools: input.tools,
+    system: input.system,
+    appendSystem: input.appendSystem,
+    temperature: input.temperature,
+    agent: agent.name,
+    model: await resolveModel({
+      model: input.model,
+      agent,
+    }),
+    compactionModel: input.compactionModel,
+  };
+
+  const parts = await Promise.all(
+    input.parts.map(async (part): Promise<MessageV2.Part[]> => {
+      if (part.type === 'file') {
+        const url = new URL(part.url);
+        switch (url.protocol) {
+          case 'data:':
+            if (part.mime === 'text/plain') {
+              return [
+                {
+                  id: Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                  type: 'text',
+                  synthetic: true,
+                  text: `Called the Read tool with the following input: ${JSON.stringify({ filePath: part.filename })}`,
+                },
+                {
+                  id: Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                  type: 'text',
+                  synthetic: true,
+                  text: Buffer.from(part.url, 'base64url').toString(),
+                },
+                {
+                  ...part,
+                  id: part.id ?? Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                },
+              ];
+            }
+            break;
+          case 'file:':
+            log.info(() => ({ message: 'file', mime: part.mime }));
+            // have to normalize, symbol search returns absolute paths
+            // Decode the pathname since URL constructor doesn't automatically decode it
+            const filepath = fileURLToPath(part.url);
+            const stat = await Bun.file(filepath).stat();
+
+            if (stat.isDirectory()) {
+              part.mime = 'application/x-directory';
+            }
+
+            if (part.mime === 'text/plain') {
+              let offset: number | undefined = undefined;
+              let limit: number | undefined = undefined;
+              const range = {
+                start: url.searchParams.get('start'),
+                end: url.searchParams.get('end'),
+              };
+              if (range.start != null) {
+                const filePathURI = part.url.split('?')[0];
+                let start = parseInt(range.start);
+                let end = range.end ? parseInt(range.end) : undefined;
+                offset = Math.max(start - 1, 0);
+                if (end) {
+                  limit = end - offset;
+                }
+              }
+              const args = { filePath: filepath, offset, limit };
+
+              const pieces: MessageV2.Part[] = [
+                {
+                  id: Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                  type: 'text',
+                  synthetic: true,
+                  text: `Called the Read tool with the following input: ${JSON.stringify(args)}`,
+                },
+              ];
+
+              await ReadTool.init()
+                .then(async (t) => {
+                  const result = await t.execute(args, {
+                    sessionID: input.sessionID,
+                    abort: new AbortController().signal,
+                    agent: input.agent!,
+                    messageID: info.id,
+                    extra: { bypassCwdCheck: true, ...info.model },
+                    metadata: async () => {},
+                  });
+                  pieces.push(
+                    {
+                      id: Identifier.ascending('part'),
+                      messageID: info.id,
+                      sessionID: input.sessionID,
+                      type: 'text',
+                      synthetic: true,
+                      text: result.output,
+                    },
+                    {
+                      ...part,
+                      id: part.id ?? Identifier.ascending('part'),
+                      messageID: info.id,
+                      sessionID: input.sessionID,
+                    }
+                  );
+                })
+                .catch((error) => {
+                  log.error(() => ({
+                    message: 'failed to read file',
+                    error,
+                  }));
+                  const message =
+                    error instanceof Error ? error.message : error.toString();
+                  Bus.publish(Session.Event.Error, {
+                    sessionID: input.sessionID,
+                    error: new NamedError.Unknown({
+                      message,
+                    }).toObject(),
+                  });
+                  pieces.push({
+                    id: Identifier.ascending('part'),
+                    messageID: info.id,
+                    sessionID: input.sessionID,
+                    type: 'text',
+                    synthetic: true,
+                    text: `Read tool failed to read ${filepath} with the following error: ${message}`,
+                  });
+                });
+
+              return pieces;
+            }
+
+            if (part.mime === 'application/x-directory') {
+              const args = { path: filepath };
+              const result = await ListTool.init().then((t) =>
+                t.execute(args, {
+                  sessionID: input.sessionID,
+                  abort: new AbortController().signal,
+                  agent: input.agent!,
+                  messageID: info.id,
+                  extra: { bypassCwdCheck: true },
+                  metadata: async () => {},
+                })
+              );
+              return [
+                {
+                  id: Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                  type: 'text',
+                  synthetic: true,
+                  text: `Called the list tool with the following input: ${JSON.stringify(args)}`,
+                },
+                {
+                  id: Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                  type: 'text',
+                  synthetic: true,
+                  text: result.output,
+                },
+                {
+                  ...part,
+                  id: part.id ?? Identifier.ascending('part'),
+                  messageID: info.id,
+                  sessionID: input.sessionID,
+                },
+              ];
+            }
+
+            const file = Bun.file(filepath);
+            FileTime.read(input.sessionID, filepath);
+            return [
+              {
+                id: Identifier.ascending('part'),
+                messageID: info.id,
+                sessionID: input.sessionID,
+                type: 'text',
+                text: `Called the Read tool with the following input: {\"filePath\":\"${filepath}\"}`,
+                synthetic: true,
+              },
+              {
+                id: part.id ?? Identifier.ascending('part'),
+                messageID: info.id,
+                sessionID: input.sessionID,
+                type: 'file',
+                url:
+                  `data:${part.mime};base64,` +
+                  Buffer.from(await file.bytes()).toString('base64'),
+                mime: part.mime,
+                filename: part.filename!,
+                source: part.source,
+              },
+            ];
+        }
+      }
+
+      if (part.type === 'agent') {
+        return [
+          {
+            id: Identifier.ascending('part'),
+            ...part,
+            messageID: info.id,
+            sessionID: input.sessionID,
+          },
+          {
+            id: Identifier.ascending('part'),
+            messageID: info.id,
+            sessionID: input.sessionID,
+            type: 'text',
+            synthetic: true,
+            text:
+              'Use the above message and context to generate a prompt and call the task tool with subagent: ' +
+              part.name,
+          },
+        ];
+      }
+
+      return [
+        {
+          id: Identifier.ascending('part'),
+          ...part,
+          messageID: info.id,
+          sessionID: input.sessionID,
+        },
+      ];
+    })
+  ).then((x) => x.flat());
+
+  await Session.updateMessage(info);
+  for (const part of parts) {
+    await Session.updatePart(part);
+  }
+
+  return {
+    info,
+    parts,
+  };
+}
